<?php
$report_url = function ($group) use ($year_id, $grade, $district) { return site_url('reports').'?'.http_build_query(array('school_year_id' => (int) $year_id, 'grade_level' => $grade, 'district' => $district, 'group' => $group)); };
?>
<div class="learner-workspace learner-directory directory-refined school-report">
    <header class="learner-page-heading"><div><p class="learner-eyebrow">REPORTS / LEARNER GROUPS</p><h1>Learner Group Reports</h1><p><?php echo $school ? 'A detailed view of your school’s learners by education program.' : 'A detailed view of learners in your '.e($organization_label).' by education program.'; ?></p></div><button class="btn btn-outline-primary report-print" type="button" hidden><i class="bi bi-printer" aria-hidden="true"></i> Print This Page</button></header>
    <div class="directory-context"><span><i class="bi bi-building" aria-hidden="true"></i> <?php echo e($organization_name); ?></span><?php if ($district): ?><span><i class="bi bi-geo-alt" aria-hidden="true"></i> <?php echo e($district); ?></span><?php endif; ?><span><i class="bi bi-calendar3" aria-hidden="true"></i> <?php echo $year ? 'SY '.e($year->year_label) : 'No School Year'; ?></span><span><?php echo e($grade ?: 'All Grade Levels'); ?></span><span>Generated <?php echo e((new DateTimeImmutable('now', new DateTimeZone('Asia/Manila')))->format('M j, Y, g:i A').' PHT'); ?></span></div>
    <section class="directory-filter-card report-filters" aria-label="Report Filters"><form method="get" action="<?php echo site_url('reports'); ?>" class="directory-filters <?php echo $districts ? 'has-district' : ''; ?>">
        <div><label for="report-year" class="form-label">School Year</label><select class="form-select" name="school_year_id" id="report-year"><?php foreach ($years as $sy): ?><option value="<?php echo (int) $sy->id; ?>" <?php echo (int) $year_id === (int) $sy->id ? 'selected' : ''; ?>><?php echo e($sy->year_label); ?><?php echo $sy->status === 'closed' ? ' (Closed)' : ''; ?></option><?php endforeach; ?></select></div>
        <div><label for="report-grade" class="form-label">Grade Level</label><select class="form-select" name="grade_level" id="report-grade"><option value="">All Grades</option><?php foreach ($grades as $g): ?><option <?php echo $grade === $g ? 'selected' : ''; ?>><?php echo e($g); ?></option><?php endforeach; ?></select></div>
        <?php if ($districts): ?><div><label for="report-district" class="form-label">District (Municipality/City)</label><select class="form-select" name="district" id="report-district"><option value="">All Districts</option><?php foreach ($districts as $district_option): ?><option value="<?php echo e($district_option); ?>" <?php echo $district === $district_option ? 'selected' : ''; ?>><?php echo e($district_option); ?></option><?php endforeach; ?></select></div><?php endif; ?>
        <div><label for="report-group" class="form-label">Learner Group</label><select class="form-select" name="group" id="report-group"><option value="all">All Groups</option><?php foreach ($groups as $code => $label): ?><option value="<?php echo e($code); ?>" <?php echo $selected_group === $code ? 'selected' : ''; ?>><?php echo e($label); ?></option><?php endforeach; ?></select></div>
        <button class="btn directory-filter-submit" type="submit">Generate Report</button>
    </form></section>
    <section class="directory-overview" aria-label="Report Overview">
        <?php foreach (array('all' => array('Unique Learners', 'bi-people', ''), 'multiple' => array('Multiple Programs', 'bi-intersect', 'is-purple'), 'untagged' => array('No Program Tags', 'bi-person-vcard', 'is-amber')) as $key => $card): ?><div class="directory-overview-card"><span class="directory-overview-icon <?php echo e($card[2]); ?>"><i class="bi <?php echo e($card[1]); ?>" aria-hidden="true"></i></span><div><p><?php echo e($card[0]); ?></p><strong><?php echo number_format($summary[$key]['total']); ?></strong><span>Selected School Year<?php echo $grade ? ' · '.e($grade) : ''; ?></span></div></div><?php endforeach; ?>
    </section>
    <section class="directory-table-card report-summary-card" aria-labelledby="report-summary-title"><div class="directory-table-toolbar"><div><h2 id="report-summary-title">Learner Group Summary</h2><p>Counts reflect the selected school year, grade level, and district.</p></div><?php $this->load->view('school/reports/export_buttons', array('export_section' => 'summary', 'export_label' => 'Learner Group Summary', 'year_id' => $year_id, 'grade' => $grade, 'district' => $district)); ?></div><div class="table-responsive"><table class="table report-summary-table"><thead><tr><th scope="col">Learner Group</th><th scope="col">Male</th><th scope="col">Female</th><th scope="col">Total</th><th scope="col" class="report-screen-only">Details</th></tr></thead><tbody>
        <?php foreach ($groups as $code => $label): ?><tr <?php echo $selected_group === $code ? 'class="report-selected-row"' : ''; ?>><th scope="row"><?php echo e($label); ?></th><td><?php echo number_format($summary[$code]['male']); ?></td><td><?php echo number_format($summary[$code]['female']); ?></td><td><strong><?php echo number_format($summary[$code]['total']); ?></strong></td><td class="report-screen-only"><a href="<?php echo e($report_url($code)); ?>">View Group <i class="bi bi-arrow-right" aria-hidden="true"></i></a></td></tr><?php endforeach; ?>
        <tr class="report-unique-total"><th scope="row">Unique Learners</th><td><?php echo number_format($summary['all']['male']); ?></td><td><?php echo number_format($summary['all']['female']); ?></td><td><strong><?php echo number_format($summary['all']['total']); ?></strong></td><td class="report-screen-only"></td></tr>
    </tbody></table></div></section>
    <p class="directory-footnote"><i class="bi bi-info-circle" aria-hidden="true"></i> Learners with multiple tags appear in each applicable program and in Multiple Programs. Group totals overlap; Unique Learners counts each learner once.</p>
    <div class="report-detail-heading"><h2>Detailed Learner Lists</h2><?php if ($selected_group !== 'all'): ?><a class="report-screen-only" href="<?php echo e($report_url('all')); ?>">Show All Groups</a><?php endif; ?></div>
    <?php foreach ($sections as $code => $section): ?>
    <section class="directory-table-card report-detail-card" aria-labelledby="report-<?php echo e($code); ?>-title">
        <div class="directory-table-toolbar"><div><h2 id="report-<?php echo e($code); ?>-title"><?php echo e($section['label']); ?> <span><?php echo number_format($section['total']); ?></span></h2><p><?php echo isset(programs()[$code]) ? e(programs($code)['name']) : ($code === 'multiple' ? 'Learners tagged in two or more education programs.' : 'Learners without an education program tag.'); ?></p></div><?php $this->load->view('school/reports/export_buttons', array('export_section' => $code, 'export_label' => $section['label'], 'year_id' => $year_id, 'grade' => $grade, 'district' => $district)); ?></div>
        <div class="directory-table-scroll" role="region" aria-label="<?php echo e($section['label'].' Learner Details'); ?>" tabindex="0"><table class="table directory-table report-detail-table"><thead><tr><th scope="col">#</th><th scope="col">Learner Name</th><?php if ( ! $school): ?><th scope="col">School</th><?php endif; ?><th scope="col">LRN</th><th scope="col">Sex</th><th scope="col">Date of Birth</th><th scope="col">Grade / Section</th><th scope="col">Program Tags</th><th scope="col">Enrollment Status</th></tr></thead><tbody>
            <?php foreach ($section['rows'] as $index => $row): ?><tr><td><?php echo $section['offset'] + $index + 1; ?></td><td><strong><?php echo e($row->last_name.', '.$row->first_name.($row->middle_name ? ' '.$row->middle_name : '').($row->extension_name ? ' '.$row->extension_name : '')); ?></strong></td><?php if ( ! $school): ?><td><?php echo e($row->school_name); ?></td><?php endif; ?><td><span class="directory-lrn"><?php echo e($row->lrn ?: 'Not Assigned'); ?></span></td><td><?php echo e($row->sex); ?></td><td><?php echo e($row->date_of_birth ?: 'Not Recorded'); ?></td><td><strong class="directory-grade"><?php echo e($row->grade_level ?: 'Not Set'); ?></strong><span class="directory-section"><?php echo e($row->section ?: 'No Section'); ?></span></td><td><div class="directory-program-tags"><?php if ($row->program_codes): foreach (explode(',', $row->program_codes) as $tag_code): $tag = programs($tag_code); if ( ! $tag) continue; ?><span class="directory-program-tag" style="--tag-color: <?php echo e($tag['color']); ?>"><?php echo e($tag_code === 'spfl' ? 'FL / SPFL' : $tag['short']); ?></span><?php endforeach; else: ?>No Program Tags<?php endif; ?></div></td><td><?php echo e($row->enrollment_status); ?></td></tr><?php endforeach; ?>
            <?php if ( ! $section['rows']): ?><tr><td colspan="<?php echo $school ? 8 : 9; ?>" class="text-center text-muted py-4">No learners in this group for the selected filters.</td></tr><?php endif; ?>
        </tbody></table></div>
        <footer class="directory-table-footer"><p><?php if ($section['total']): ?>Showing <strong><?php echo number_format($section['offset'] + 1); ?>–<?php echo number_format($section['offset'] + count($section['rows'])); ?></strong> of <strong><?php echo number_format($section['total']); ?></strong> learners<?php else: ?>0 learners<?php endif; ?></p><?php if ($selected_group === 'all' && $section['total'] > count($section['rows'])): ?><a class="report-screen-only" href="<?php echo e($report_url($code)); ?>">View Full Group <i class="bi bi-arrow-right" aria-hidden="true"></i></a><?php endif; ?><?php echo $section['pagination']; ?></footer>
    </section>
    <?php endforeach; ?>
    <p class="directory-footnote report-print-note">Printing includes only the rows shown on this page. Section downloads include all matching records. In All Groups, up to 25 learners are shown per group. Use View Full Group and pagination to review additional records.</p>
</div>
<script>
(function () {
    var button = document.querySelector('.report-print');
    button.hidden = false;
    button.addEventListener('click', function () { window.print(); });
}());
</script>
